/** Boats already listed with a broker — never pitch these. */
export const disqualified = leads.filter((l) => l.verdict === "DISQUALIFIED");

/** Real FSBO targets, comped ones first. */
export const sendQueue = leads.filter((l) => l.verdict !== "DISQUALIFIED");

/** The Messenger cadence, in order. Stage 2 only goes out after a seller
 *  confirms it is a private sale. */
export function messageScript(lead: Lead) {
  const money = (n: number) => "$" + n.toLocaleString();
  return [
    { step: "Opener", body: "Is this a broker listing?" },
    {
      step: "If private seller",
      body:
        "Solid boat. Quick question are you firm on the price or open to the right buyer? I'm with Jeff Brown Yachts & GrayYachts.\n" +
        "We work in the premium marine market out in the PNW.\n" +
        "I may have a buyer interested",
    },
    { step: "No reply", body: "Thoughts?" },
    {
      step: "Terms",
      body:
        lead.relistAt && lead.ask
          ? "Here's how I'd structure it — I'd price the boat higher to factor in an extra 5%, so it lists at " +
            money(lead.relistAt) +
            ". My commission is 5%, taken off your current listing price. You'd net " +
            money(lead.ask) +
            " — your full asking price. Let me know if this is something that would work for you?"
          : "",
    },
  ];
}
